const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$tests=@(
 'https://forum.thegradcafe.com/search.json?q=tutor',
 'https://talk.collegeconfidential.com/search.json?q=tutor',
 'https://forum.thegradcafe.com/latest.json',
 'https://talk.collegeconfidential.com/latest.json'
)
foreach($u in $tests){
  $code = curl.exe -s -o "$env:TEMP\\d.json" -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 30 --compressed $u
  Write-Output "== $code  $u"
  $c = Get-Content "$env:TEMP\\d.json" -Raw -ErrorAction SilentlyContinue
  if($c){ Write-Output ($c.Substring(0,[Math]::Min(200,$c.Length))) }
}
`;
const r = await tools.pwsh({ description: "Probe Discourse JSON APIs", command: cmd, timeoutMs: 180000 });
console.log(r.kind === 'foreground' ? r.stdout.text + "|ERR:" + r.stderr.text : JSON.stringify(r));
